const galleryContainer = document.querySelector('.gallery');

// Шаблон створення розмітки строго за новим ТЗ (без data-source)
const createGalleryMarkup = imagesArray => {
  return imagesArray
    .map(({ preview, original, description }) => {
      return `
        <li class="gallery-item">
          <a class="gallery-link" href="${original}">
            <img
              class="gallery-image"
              src="${preview}"
              alt="${description}"
            />
          </a>
        </li>
      `;
    })
    .join('');
};

// Додаємо елементи в DOM
galleryContainer.innerHTML = createGalleryMarkup(images);

// Ініціалізація SimpleLightbox ПОЗА межами будь-яких функцій
// Додаємо налаштування: підпис знизу, береться з alt, затримка 250мс
new SimpleLightbox('.gallery a', {
  captionsData: 'alt',
  captionPosition: 'bottom',
  captionDelay: 250,
});
